# Recompute bootstrap for all lines with combined data (line1 already full, lines 2-5 combined)
lines = [1,2,3,4,5]
combined_data = {1: line1}
for l in [2,3,4,5]:
    if l == 3:
        combined_data[l] = line3_all  # includes experiment
    else:
        combined_data[l] = lines_2_5_full[lines_2_5_full['line']==l]
# Bootstrap
B = 1000
coeff_samples = {l: {'a':[], 'b':[], 'c':[]} for l in lines}
for l in lines:
    data = combined_data[l]
    drivers = data['driver'].values
    outcomes = data['outcome'].values
    n = len(drivers)
    for b in range(B):
        idx = np.random.choice(n, n, replace=True)
        d_b = drivers[idx]
        o_b = outcomes[idx]
        try:
            c = np.polyfit(d_b, o_b, 2)
        except:
            continue
        coeff_samples[l]['a'].append(c[0])
        coeff_samples[l]['b'].append(c[1])
        coeff_samples[l]['c'].append(c[2])
# Compute means and stds
coeff_means = {}
coeff_stds = {}
residual_stds = {}
for l in lines:
    coeff_means[l] = (np.mean(coeff_samples[l]['a']), np.mean(coeff_samples[l]['b']), np.mean(coeff_samples[l]['c']))
    coeff_stds[l] = (np.std(coeff_samples[l]['a']), np.std(coeff_samples[l]['b']), np.std(coeff_samples[l]['c']))
    # Residual std from fit to full dataset
    drivers = combined_data[l]['driver'].values
    outcomes = combined_data[l]['outcome'].values
    c = np.polyfit(drivers, outcomes, 2)
    pred = np.polyval(c, drivers)
    residual_stds[l] = np.std(outcomes - pred)
    print(f"Line {l}: a={coeff_means[l][0]:.4f}±{coeff_stds[l][0]:.4f}, b={coeff_means[l][1]:.4f}±{coeff_stds[l][1]:.4f}, c={coeff_means[l][2]:.4f}±{coeff_stds[l][2]:.4f}, resid_std={residual_stds[l]:.4f}")

# Check predictive coverage for high driver for lines 2,4,5
def predictive_interval(line, driver, n_sim=100000):
    rng = np.random.default_rng(42)
    sim = []
    for _ in range(n_sim):
        idx = rng.integers(0, len(coeff_samples[line]['a']))
        a = coeff_samples[line]['a'][idx]
        b = coeff_samples[line]['b'][idx]
        c = coeff_samples[line]['c'][idx]
        mean = a*driver**2 + b*driver + c
        outcome = rng.normal(mean, residual_stds[line])
        sim.append(outcome)
    return np.percentile(sim, [10,90])

for l in [2,4,5]:
    obs_high = lines_2_5_full[(lines_2_5_full['line']==l) & (lines_2_5_full['driver']>8)]
    if len(obs_high) > 0:
        p10, p90 = predictive_interval(l, 10)
        print(f"Line {l} driver=10 predictive 10th-90th: [{p10:.2f}, {p90:.2f}], observed high-driver outcomes: {list(obs_high['outcome'].values)}")
        # Check if observed within interval
        for o in obs_high['outcome']:
            if o < p10 or o > p90:
                print(f"  -> Observation {o:.2f} outside interval!")
    else:
        print(f"Line {l} no high-driver observed data.")

# Quick simulation check
def simulate(line, driver, n=10000, seed=42):
    rng = np.random.default_rng(seed)
    a = -0.3251
    b = 3.2458
    intercepts = {1:14.1561, 2:13.6530, 3:13.9434, 4:13.9658, 5:13.8977}
    mean = intercepts[line] + b*driver + a*driver**2
    sigma = 0.705
    return rng.normal(mean, sigma, n)

for line in [2,3,4,5]:
    print(f"\nLine {line}:")
    for d in [0,5,10]:
        samples = simulate(line, d, n=10000)
        print(f"  driver {d}: mean {samples.mean():.2f}, 10th {np.percentile(samples,10):.2f}, 90th {np.percentile(samples,90):.2f}")
